begin;
create table if not exists public.competition_assignments(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,match_id uuid references public.matches(id) on delete cascade,member_id uuid not null references public.team_members(id) on delete cascade,role text not null check(role in ('scout_red_1','scout_red_2','scout_red_3','scout_blue_1','scout_blue_2','scout_blue_3','drive_team','pit_crew','strategy','media','other')),station text,notes text,status text not null default 'assigned' check(status in ('assigned','confirmed','completed','absent')),assigned_by uuid references public.team_members(id) on delete set null default auth.uid(),created_at timestamptz not null default now(),unique(event_id,match_id,member_id,role));
create table if not exists public.competition_pit_queue(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,match_id uuid references public.matches(id) on delete set null,title text not null,details text,severity text not null default 'medium' check(severity in ('low','medium','high','critical')),status text not null default 'open' check(status in ('open','in_progress','verify','done')),owner_id uuid references public.team_members(id) on delete set null,robot_issue_id uuid references public.robot_issues(id) on delete set null,reported_by uuid not null references public.team_members(id) on delete restrict default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.competition_briefings(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,match_id uuid references public.matches(id) on delete cascade,headline text not null,content text not null,briefing_type text not null default 'strategy' check(briefing_type in ('strategy','pit','schedule','urgent')),created_by uuid not null references public.team_members(id) on delete restrict default auth.uid(),created_at timestamptz not null default now());
create index if not exists competition_assignments_event_idx on public.competition_assignments(event_id,match_id,member_id);create index if not exists competition_pit_event_idx on public.competition_pit_queue(event_id,status,severity,updated_at desc);create index if not exists competition_briefings_event_idx on public.competition_briefings(event_id,created_at desc);
alter table public.competition_assignments enable row level security;alter table public.competition_pit_queue enable row level security;alter table public.competition_briefings enable row level security;
do $$declare t text;begin foreach t in array array['competition_assignments','competition_pit_queue','competition_briefings'] loop execute format('drop policy if exists "members view %1$s" on public.%1$I',t);execute format('create policy "members view %1$s" on public.%1$I for select to authenticated using(public.current_team_role() is not null)',t);execute format('drop policy if exists "members create %1$s" on public.%1$I',t);execute format('create policy "members create %1$s" on public.%1$I for insert to authenticated with check(public.current_team_role() is not null)',t);execute format('drop policy if exists "members update %1$s" on public.%1$I',t);execute format('create policy "members update %1$s" on public.%1$I for update to authenticated using(public.current_team_role() is not null) with check(public.current_team_role() is not null)',t);execute format('drop policy if exists "admins delete %1$s" on public.%1$I',t);execute format('create policy "admins delete %1$s" on public.%1$I for delete to authenticated using(public.is_admin())',t);end loop;end$$;
commit;
